const API_BASE_URL=String(window.WORKERIN_CONFIG?.apiBaseUrl||'').replace(/\/+$/,'');
function apiUrl(path){if(!API_BASE_URL&&location.hostname.endsWith('netlify.app'))throw new Error('O frontend está publicado, mas falta configurar a URL pública da API WorkerIN no arquivo workerin-config.js.');return new URL(path,`${API_BASE_URL||location.origin}/`).href}
function apiSocketUrl(path,query={}){const url=new URL(API_BASE_URL||location.origin);url.protocol=url.protocol==='https:'?'wss:':'ws:';url.pathname=path;url.search=new URLSearchParams(query).toString();return url.href}
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let discoveryCoordinates=null;
function imageUrl(id,width=900){const value=String(id||'');if(/^https?:\/\//i.test(value)){try{const url=new URL(value,location.href);return ['http:','https:'].includes(url.protocol)?url.href:''}catch{return ''}}return `https://images.unsplash.com/${encodeURIComponent(value)}?auto=format&fit=crop&w=${width}&q=85`}
