document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="edit-own-profile-modal" aria-hidden="true"><section class="modal auth-modal"><div class="modal-head"><div><div class="eyebrow"><span class="eyebrow-line"></span> SEU PERFIL</div><h2>Editar apresentação</h2></div><button class="modal-close" data-close aria-label="Fechar">×</button></div><form id="edit-own-profile-form"><label class="field-label">Nome público</label><input class="auth-input" name="name" maxlength="100" required/><label class="field-label">Cargo ou especialidade</label><input class="auth-input" name="role" maxlength="120" required/><label class="field-label">Área de atuação</label><input class="auth-input" name="area" maxlength="80" required/><label class="field-label">Cidade</label><input class="auth-input" name="city" maxlength="120" required/><label class="field-label">Valor ou orçamento por hora (R$)</label><input class="auth-input" name="rate" type="number" min="0" required/><label class="field-label">Modelo de trabalho</label><select class="auth-input" name="workModes" multiple><option>Remoto</option><option>Híbrido</option><option>Presencial</option></select><label class="field-label">Competências (separadas por vírgula)</label><input class="auth-input" name="skills"/><label class="field-label">Biografia</label><textarea class="auth-input" name="bio" rows="4" maxlength="1200"></textarea><label class="check-option"><input type="checkbox" name="available"/><span class="custom-check">✓</span><span><strong>Disponível para novos projetos</strong></span></label><p id="edit-profile-error" class="auth-error" role="alert" hidden></p><button class="apply-button auth-submit" type="submit">Salvar perfil</button></form></section></div>`);
document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="start-live-modal" aria-hidden="true"><section class="modal auth-modal"><div class="modal-head"><div><div class="eyebrow"><span class="live-dot"></span> AO VIVO</div><h2>Inicie sua transmissão</h2></div><button class="modal-close" data-close aria-label="Fechar">×</button></div><form id="start-live-form"><label class="field-label">Título da live</label><input class="auth-input" name="title" maxlength="120" required minlength="3" placeholder="Ex.: Criando um app com React"/><label class="field-label">Área</label><input class="auth-input" name="area" maxlength="80" placeholder="Engenharia de software"/><p class="live-consent-note">Sua câmera e seu microfone serão ativados depois de tocar em “Começar live”.</p><p id="start-live-error" class="auth-error" role="alert" hidden></p><button class="apply-button auth-submit" type="submit">Começar live</button></form></section></div><div class="modal-backdrop" id="watch-live-modal" aria-hidden="true"><section class="modal live-player-modal"><button class="modal-close floating-close" id="live-player-close" aria-label="Fechar">×</button><video id="live-player-video" autoplay playsinline></video><div class="live-player-overlay"><span class="live-now" id="live-player-badge"><i></i> CONECTANDO</span><h2 id="live-player-title">Transmissão ao vivo</h2><p id="live-player-status">Conectando com a transmissão…</p><button class="apply-button" id="end-live-button" hidden>Encerrar transmissão</button></div></section></div>`);
$('.conversation-empty').id='conversation-empty';$('.inbox').append($('#chat-panel'));
const authToken=()=>sessionStorage.getItem('workerin_token');
async function refreshAuthSession(){const refreshToken=sessionStorage.getItem('workerin_refresh_token');if(!refreshToken)return false;const response=await fetch(apiUrl('/api/auth/refresh'),{method:'POST',headers:{accept:'application/json','content-type':'application/json'},body:JSON.stringify({refreshToken})});const result=await response.json().catch(()=>({}));if(!response.ok||!result.token){sessionStorage.removeItem('workerin_token');sessionStorage.removeItem('workerin_refresh_token');sessionStorage.removeItem('workerin_profile_id');return false}sessionStorage.setItem('workerin_token',result.token);if(result.refreshToken)sessionStorage.setItem('workerin_refresh_token',result.refreshToken);sessionStorage.setItem('workerin_profile_id',result.profile?.id||'');currentProfile=result.profile;return true}
async function apiRequest(path,options={}){if(location.protocol==='file:')throw new Error('Abra o WorkerIN em http://localhost:4173 para usar cadastro, login e dados salvos.');const request=()=>{const headers={accept:'application/json',...(options.body?{'content-type':'application/json'}:{}),...(authToken()?{authorization:`Bearer ${authToken()}`}:{}) ,...(options.headers||{})};return fetch(apiUrl(path),{...options,headers})};let response=await request();if(response.status===401&&sessionStorage.getItem('workerin_refresh_token')&&path!=='/api/auth/refresh'&&await refreshAuthSession())response=await request();const result=response.status===204?{}:await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||`Falha na API (${response.status})`);return result}
function renderPlanCard(){const card=$('#plan-card');if(!card)return;card.innerHTML=currentPlan==='pro'?'<div class="plan-card-copy"><span class="pro-kicker">SEU PLANO</span><h2>WorkerIN Pro <span>ATIVO</span></h2><p>Você pode ver visitantes e curtidas e iniciar conversas sem match.</p></div><button class="filter-button" id="open-activity">Ver atividade ↗</button>':'<div class="plan-card-copy"><span class="pro-kicker">SEU PLANO</span><h2>WorkerIN Free</h2><p>Curta perfis e converse depois de um match. Faça upgrade para descobrir visitantes e curtidas e mandar mensagem sem match.</p></div><button class="apply-button" id="upgrade-plan">Conhecer Pro · R$ 7/mês</button>';$('#upgrade-plan')?.addEventListener('click',openProModal);$('#open-activity')?.addEventListener('click',()=>{activeActivity='likes';$$('[data-activity]').forEach(b=>b.classList.toggle('chosen',b.dataset.activity===activeActivity));navigate('matches');loadAccountActivity()})}
async function loadAccountPlan(){if(!authToken()){currentPlan='free';renderPlanCard();return}try{const result=await apiRequest('/api/account/plan');currentPlan=result.plan;renderPlanCard();if(currentProfile)$('#account-button .account-text small').textContent=`${currentProfile.profileType==='company'?'Empresa':'Freelancer'} · ${currentPlan==='pro'?'Pro':'Free'}`;if(activeActivity!=='matches')renderMatches()}catch{currentPlan='free';renderPlanCard()}}
async function loadAccountActivity(){if(currentPlan!=='pro'){renderMatches();return}try{const result=await apiRequest('/api/account/activity');activityItems=result;renderMatches()}catch(error){showToast(error.message)}}
function openProModal(){if(!authToken()){setAuthMode('login');openModal('auth-modal');showToast('Entre na sua conta para ver as opções do Pro');return}$('#pro-checkout-note').textContent='Assinatura mensal de R$ 7, processada com segurança pelo Mercado Pago.';$('#pro-checkout-note').classList.remove('checkout-unavailable');openModal('pro-modal')}
async function startDirectConversation(profileId){try{const result=await apiRequest(`/api/conversations/direct/${encodeURIComponent(profileId)}`,{method:'POST',body:'{}'});await syncPrivateData();const id=String(result.conversation.id||result.conversation._id);const conversation=privateConversations.find(item=>item.id===id);navigate('messages');if(conversation)openConversation(conversation);closeModal($('#profile-modal'))}catch(error){if(error.message.includes('WorkerIN Pro'))openProModal();else showToast(error.message)}}
$('#pro-checkout').onclick=async()=>{try{const result=await apiRequest('/api/subscriptions/checkout',{method:'POST',body:JSON.stringify({plan:'pro',priceBRL:7})});if(result.url)location.assign(result.url)}catch(error){$('#pro-checkout-note').textContent=error.message;$('#pro-checkout-note').classList.add('checkout-unavailable')}};
function liveSend(event){if(liveSocket?.readyState===WebSocket.OPEN)liveSocket.send(JSON.stringify(event))}
function makeLivePeer(viewerId,host){const pc=new RTCPeerConnection({iceServers:[{urls:'stun:stun.l.google.com:19302'}]});livePeers.set(viewerId,pc);pc.onicecandidate=event=>{if(event.candidate)liveSend({type:'ice',targetId:viewerId,payload:event.candidate.toJSON()})};pc.onconnectionstatechange=()=>{if(['failed','closed','disconnected'].includes(pc.connectionState)){pc.close();livePeers.delete(viewerId)}};if(host){liveStream.getTracks().forEach(track=>pc.addTrack(track,liveStream));pc.createOffer().then(offer=>pc.setLocalDescription(offer)).then(()=>liveSend({type:'offer',targetId:viewerId,payload:pc.localDescription})).catch(()=>showToast('Não foi possível conectar a pessoa à live.'))}else{pc.ontrack=event=>{const video=$('#live-player-video');video.srcObject=event.streams[0];video.play().catch(()=>{})}}return pc}
async function openLiveSocket(sessionId,role){const{ticket}=await apiRequest('/api/auth/live-ticket',{method:'POST'});return new Promise((resolve,reject)=>{const socket=new WebSocket(apiSocketUrl('/ws/live',{sessionId,role,ticket}));liveSocket=socket;const timer=setTimeout(()=>reject(new Error('Tempo esgotado ao conectar à live.')),8000);socket.onopen=()=>{clearTimeout(timer);resolve(socket)};socket.onerror=()=>{clearTimeout(timer);reject(new Error('Não foi possível conectar à transmissão.'))};socket.onmessage=async message=>{try{const event=JSON.parse(message.data);if(event.type==='viewer-joined'&&role==='host'){const pc=makeLivePeer(event.viewerId,true);pc.onnegotiationneeded=()=>{};document.querySelector('#live-player-status').textContent=`${event.viewers} pessoa(s) assistindo`}else if(event.type==='viewer-left'&&role==='host'){livePeers.get(event.viewerId)?.close();livePeers.delete(event.viewerId);$('#live-player-status').textContent=`${event.viewers} pessoa(s) assistindo`}else if(event.type==='offer'&&role==='viewer'){const pc=makeLivePeer(event.senderId,false);await pc.setRemoteDescription(event.payload);const answer=await pc.createAnswer();await pc.setLocalDescription(answer);liveSend({type:'answer',targetId:event.senderId,payload:pc.localDescription});$('#live-player-badge').innerHTML='<i></i> AO VIVO';$('#live-player-status').textContent='Transmissão conectada'}else if(event.type==='answer'&&role==='host'){await livePeers.get(event.senderId)?.setRemoteDescription(event.payload)}else if(event.type==='ice'){await livePeers.get(event.senderId)?.addIceCandidate(event.payload)}else if(event.type==='host-ready'&&role==='host')$('#live-player-status').textContent=event.viewers?`${event.viewers} pessoa(s) aguardando`:'Sua transmissão está no ar';else if(event.type==='waiting-for-host')$('#live-player-status').textContent='Aguardando o host conectar…';else if(event.type==='ended'){showToast('A transmissão foi encerrada');closeLivePlayer(false)}}catch(error){console.warn('Live signaling:',error)}};socket.onclose=()=>{if(liveSocket===socket)liveSocket=null}})}
async function beginLive(title,area){let created=null;try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('Câmera e microfone precisam de uma conexão segura (localhost ou HTTPS).');liveStream=await navigator.mediaDevices.getUserMedia({video:true,audio:true});$('#live-player-video').srcObject=liveStream;$('#live-player-video').muted=true;$('#live-player-title').textContent=title;$('#live-player-badge').innerHTML='<i></i> PREPARANDO';$('#live-player-status').textContent='Solicitando conexão…';$('#end-live-button').hidden=false;openModal('watch-live-modal');const result=await apiRequest('/api/lives',{method:'POST',body:JSON.stringify({title,area})});created=result.live;window.currentLiveId=created.id;await openLiveSocket(created.id,'host');await refreshLives();showToast('Sua live está no ar')}catch(error){if(created)await apiRequest(`/api/lives/${created.id}`,{method:'DELETE'}).catch(()=>{});closeLivePlayer(false);$('#start-live-error').textContent=error.message;$('#start-live-error').hidden=false;openModal('start-live-modal')}}
async function joinLive(id){if(!authToken()){setAuthMode('login');openModal('auth-modal');showToast('Entre na sua conta para assistir à live');return}const live=activeLives.find(item=>item.id===id);if(!live)return;$('#live-player-video').muted=false;$('#live-player-video').srcObject=null;$('#live-player-title').textContent=live.title;$('#live-player-badge').innerHTML='<i></i> CONECTANDO';$('#live-player-status').textContent='Conectando com a transmissão…';$('#end-live-button').hidden=true;window.currentLiveId=id;openModal('watch-live-modal');try{await openLiveSocket(id,'viewer')}catch(error){$('#live-player-status').textContent=error.message;showToast(error.message)}}
async function closeLivePlayer(endHost=true){const id=window.currentLiveId,isHost=!!liveStream;window.currentLiveId=null;if(isHost&&endHost&&id)await apiRequest(`/api/lives/${id}`,{method:'DELETE'}).catch(()=>{});liveSocket?.close();liveSocket=null;livePeers.forEach(pc=>pc.close());livePeers.clear();liveStream?.getTracks().forEach(track=>track.stop());liveStream=null;const video=$('#live-player-video');if(video){video.pause();video.srcObject=null;video.muted=true}closeModal($('#watch-live-modal'));await refreshLives()}
async function uploadSelectedMedia(form){const photos=[...form.getAll('profilePhotos')].filter(file=>file instanceof File&&file.size);const intro=form.get('introFile');if(photos.length>5)throw new Error('Envie no máximo 5 fotos.');const files=[...photos,...(intro instanceof File&&intro.size?[intro]:[])];if(files.some(file=>file.size>25*1024*1024))throw new Error('Cada arquivo deve ter no máximo 25 MB.');const uploaded=await Promise.all(files.map(async file=>{const {uploadUrl,publicUrl}=await apiRequest('/api/media/upload-url',{method:'POST',body:JSON.stringify({filename:file.name,contentType:file.type})});const response=await fetch(apiUrl(uploadUrl),{method:'PUT',headers:{'content-type':file.type},body:file});if(!response.ok)throw new Error('Não foi possível enviar a mídia. Confira o MinIO e a conexão.');return{file,publicUrl}}));const photoUrls=uploaded.filter(item=>photos.includes(item.file)).map(item=>item.publicUrl);const introItem=uploaded.find(item=>item.file===intro);const update={};if(photoUrls.length)update.photos=photoUrls;if(introItem)update.introMedia={type:intro.type.startsWith('video/')?'video':'gif',src:introItem.publicUrl};if(!Object.keys(update).length)return null;return(await apiRequest('/api/profiles/me',{method:'PATCH',body:JSON.stringify(update)})).profile}
function addChatMessage(message,own=false){const row=document.createElement('div');row.className=`chat-message${own?' own':''}`;const text=document.createElement('span');text.textContent=message.content;const time=document.createElement('time');time.textContent=new Date(message.sentAt||Date.now()).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});row.append(text,time);$('#chat-messages').append(row);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight}
async function openConversation(conversation){if(!conversation)return;activeConversation=conversation;$('#conversation-empty').hidden=true;$('#chat-panel').hidden=false;$('#chat-title').textContent=conversation.person.name;$('#chat-status').textContent='Carregando…';if(chatSocket){chatSocket.close();chatSocket=null}$('#chat-messages').innerHTML='';try{const history=await apiRequest(`/chat/conversations/${encodeURIComponent(conversation.id)}/messages`,{headers:{authorization:`Bearer ${authToken()}`}});(history.messages||[]).reverse().forEach(m=>addChatMessage(m,m.senderId===currentProfile?.id));const {ticket}=await apiRequest('/api/auth/ws-ticket',{method:'POST'});chatSocket=new WebSocket(apiSocketUrl('/ws',{conversationId:conversation.id,ticket}));chatSocket.onopen=()=>$('#chat-status').textContent='Online';chatSocket.onclose=()=>$('#chat-status').textContent='Desconectado';chatSocket.onerror=()=>$('#chat-status').textContent='Reconectando…';chatSocket.onmessage=e=>{try{const event=JSON.parse(e.data);if(event.type==='message')addChatMessage(event.message,event.message.senderId===currentProfile?.id)}catch{}}}catch(error){$('#chat-status').textContent='Indisponível';showToast(error.message)}}
async function syncPrivateData(){if(!authToken())return;try{currentProfile={...(currentProfile||{}),id:sessionStorage.getItem('workerin_profile_id')};const [matchResult,conversationResult]=await Promise.all([apiRequest('/api/matches'),apiRequest('/api/conversations')]);matches=(matchResult.matches||[]).map(m=>{const other=(m.participants||[]).find(p=>String(p.id||p._id)!==currentProfile?.id)||m.participants?.[0];return other?{...mapApiProfile(other),conversationId:String(m.conversationId?._id||m.conversationId||'')}:null}).filter(Boolean);privateConversations=(conversationResult.conversations||[]).map(c=>{const other=(c.participants||[]).find(p=>String(p.id||p._id)!==currentProfile?.id)||c.participants?.[0];return other?{id:String(c.id||c._id),person:mapApiProfile(other),lastMessage:c.lastMessage,lastMessageAt:c.lastMessageAt}:null}).filter(Boolean);renderMatches();renderConversations()}catch(error){showToast(error.message)}}
function setAuthMode(mode){const isRegister=mode==='register';$('#auth-register-fields').hidden=!isRegister;$('#auth-title').textContent=isRegister?'Crie seu perfil WorkerIN':'Acesse sua conta';$('.auth-submit').textContent=isRegister?'Criar perfil':'Entrar';$$('[data-auth-mode]').forEach(b=>b.classList.toggle('chosen',b.dataset.authMode===mode));$('#auth-error').hidden=true;$('#auth-form').elements.namedItem('password').autocomplete=isRegister?'new-password':'current-password';$('#auth-register-fields').querySelectorAll('input,select,textarea').forEach(el=>el.required=isRegister&&['profileType','name','area','role','city','rate'].includes(el.name));const company=isRegister&&profileTypeField.value==='company';$('.person-fields').hidden=company;$('#auth-register-fields [name="age"]').required=isRegister&&!company;$('#auth-register-fields [name="gender"]').required=isRegister&&!company}
function renderOwnProfile(profile=currentProfile){if(!profile)return;const isCompany=profile.profileType==='company',photo=profile.photos?.[0]||profile.photo||'photo-1486406146926-c627a92ad1ab';$('#profile-view .section-heading .eyebrow').innerHTML=`<span class="eyebrow-line"></span> ${isCompany?'PERFIL DA EMPRESA':'PERFIL PROFISSIONAL'}`;$('#profile-view .section-heading h1').innerHTML=`${escapeHTML(profile.name)}<br><em>${isCompany?'atrai talentos.':'atrai projetos.'}</em>`;$('#profile-view .section-heading p').textContent=isCompany?'Apresente sua empresa e publique oportunidades para encontrar talentos.':'Apresente sua experiência para encontrar empresas e projetos alinhados.';$('#profile-view .company-profile').innerHTML=`<div class="company-cover"></div><div class="company-body"><img class="company-avatar" src="${imageUrl(photo,180)}" alt="Foto de ${escapeHTML(profile.name)}"><span class="verified-pill">${profile.verified?'✓ Perfil verificado':'Perfil WorkerIN'}</span><h2>${escapeHTML(profile.name)}</h2><p>${escapeHTML(profile.bio||'Conte um pouco sobre sua experiência e o que você quer construir.')}</p><div class="profile-tags"><span>📍 ${escapeHTML(profile.city)}</span><span>💻 ${escapeHTML(profile.role)}</span><span>R$ ${Number(profile.rate)||0}/hora</span>${(profile.skills||[]).slice(0,4).map(skill=>`<span>${escapeHTML(skill)}</span>`).join('')}</div></div>`;$('#account-button .account-text strong').textContent=profile.name;$('#account-button .account-text small').textContent=`${isCompany?'Empresa':'Freelancer'} · ${currentPlan==='pro'?'Pro':'Free'}`;renderPlanCard()}
function openOwnProfileEditor(){if(!authToken()){setAuthMode('login');openModal('auth-modal');return}const form=$('#edit-own-profile-form');const p=currentProfile||{};for(const key of ['name','role','area','city','rate','bio'])form.elements.namedItem(key).value=p[key]??'';const modes=new Set(p.work||p.workModes||[]);[...form.elements.namedItem('workModes').options].forEach(option=>option.selected=modes.has(option.value));form.elements.namedItem('skills').value=(p.skills||[]).join(', ');form.elements.namedItem('available').checked=p.available!==false;$('#edit-profile-error').hidden=true;openModal('edit-own-profile-modal')}
